type BoundedStorageDriver = Omit<StorageDriver, 'query'> & {
  query<K extends StoredRecord['kindRecord']>(
    query: StorageQuery<K> & { limit: number },
  ): Promise<RecordOfKind<K>[]>
}

const OUTCOME_GUARDED_STORAGE_READS = new Set<keyof StorageDriver>([
  'runtimeLeaseActive',
  'inspect',
  'getSpace',
  'migrationHistory',
  'get',
  'query',
  'count',
  'lexicalSearch',
  'vectorSearch',
  'exportRecords',
])

function outcomeGuardedStorageDriver(
  driver: BoundedStorageDriver,
  begin: () => number,
  finish: (epoch: number) => void,
): BoundedStorageDriver {
  return new Proxy(driver, {
    get(target, property) {
      const member = Reflect.get(target, property, target) as unknown
      if (typeof member !== 'function') return member
      const bound = member.bind(target) as (...args: readonly unknown[]) => unknown
      if (!OUTCOME_GUARDED_STORAGE_READS.has(property as keyof StorageDriver)) return bound
      return (...args: readonly unknown[]) => {
        const epoch = begin()
        return Promise.resolve(bound(...args)).then(
          (value) => {
            finish(epoch)
            return value
          },
          (error: unknown) => {
            finish(epoch)
            throw error
          },
        )
      }
    },
  }) as BoundedStorageDriver
}

