function derivationRecordKey(kind: StoredRecord['kindRecord'], id: string): string {
  return `${kind}\u0000${id}`
}

function createDerivationPlanningOverlay(
  plannedPuts: readonly StoredRecord[],
  plannedDeletes: readonly { kind: StoredRecord['kindRecord']; id: string }[],
): DerivationPlanningOverlay {
  const puts = new Map<string, StoredRecord>()
  for (const record of plannedPuts) {
    puts.set(derivationRecordKey(record.kindRecord, record.id), record)
  }
  const derivationsByKey = latestDerivationsByKey(
    [...puts.values()].filter(
      (record): record is StoredDerivation => record.kindRecord === 'derivation',
    ),
  )
  return {
    puts,
    deletes: new Set(
      plannedDeletes.map((deletion) => derivationRecordKey(deletion.kind, deletion.id)),
    ),
    derivationsByKey,
  }
}

function normalizeArchiveLimits(
  input: ArchiveLimits | undefined,
  label: string,
  defaults: NormalizedArchiveLimits,
  maximums: NormalizedArchiveLimits,
): NormalizedArchiveLimits {
  if (
    input !== undefined &&
    (typeof input !== 'object' || input === null || Array.isArray(input))
  ) {
    throw new MemoryError('invalid_input', `${label} must be an object`)
  }
  if (input !== undefined) {
    const unknown = Object.keys(input).find((key) => key !== 'maxRecords' && key !== 'maxBytes')
    if (unknown !== undefined) {
      throw new MemoryError('invalid_input', `${label}.${unknown} is not supported`)
    }
  }
  const normalized = {
    maxRecords: input?.maxRecords ?? defaults.maxRecords,
    maxBytes: input?.maxBytes ?? defaults.maxBytes,
  }
  for (const [field, value] of Object.entries(normalized) as [
    keyof NormalizedArchiveLimits,
    number,
  ][]) {
    if (!Number.isSafeInteger(value) || value < 1 || value > maximums[field]) {
      throw new MemoryError(
        'invalid_input',
        `${label}.${field} must be between 1 and ${maximums[field]}`,
      )
    }
  }
  return normalized
}

function normalizeDerivationWorkLimits(
  input: DerivationWorkLimits | undefined,
): NormalizedDerivationWorkLimits {
  if (
    input !== undefined &&
    (typeof input !== 'object' || input === null || Array.isArray(input))
  ) {
    throw new MemoryError('invalid_input', 'workLimits must be an object')
  }
  const allowed = new Set(['maxRecords', 'maxBytes', 'maxGraphNodes', 'maxGraphEdges'])
  if (input !== undefined) {
    const unknown = Object.keys(input).find((key) => !allowed.has(key))
    if (unknown !== undefined) {
      throw new MemoryError('invalid_input', `workLimits.${unknown} is not supported`)
    }
  }
  const limits: NormalizedDerivationWorkLimits = {
    maxRecords: input?.maxRecords ?? DEFAULT_DERIVATION_WORK_RECORDS,
    maxBytes: input?.maxBytes ?? DEFAULT_DERIVATION_WORK_BYTES,
    maxGraphNodes: input?.maxGraphNodes ?? DEFAULT_DERIVATION_GRAPH_NODES,
    maxGraphEdges: input?.maxGraphEdges ?? DEFAULT_DERIVATION_GRAPH_EDGES,
  }
  for (const [field, value, maximum] of [
    ['maxRecords', limits.maxRecords, MAX_DERIVATION_WORK_RECORDS],
    ['maxBytes', limits.maxBytes, MAX_DERIVATION_WORK_BYTES],
    ['maxGraphNodes', limits.maxGraphNodes, MAX_DERIVATION_GRAPH_NODES],
    ['maxGraphEdges', limits.maxGraphEdges, MAX_DERIVATION_GRAPH_EDGES],
  ] as const) {
    if (!Number.isSafeInteger(value) || value < 1 || value > maximum) {
      throw new MemoryError('invalid_input', `workLimits.${field} must be between 1 and ${maximum}`)
    }
  }
  return limits
}

function derivationWorkExceeded(
  dimension: 'records' | 'bytes' | 'graph_nodes' | 'graph_edges',
  required: number,
  maximum: number,
): MemoryError {
  return new MemoryError('result_too_large', `derivation planning exceeds ${dimension}`, {
    details: { phase: 'derivation', dimension, required, maximum },
  })
}

function createDerivationPlanningState(
  limits: NormalizedDerivationWorkLimits,
): DerivationPlanningState {
  return {
    limits,
    loaded: new Map(),
    bytes: 0,
    graphNodes: new Set(),
    graphEdges: new Set(),
    currentByKey: new Map(),
    missing: new Set(),
    premiseDerivationKeys: new Map(),
    conclusionDerivationKeys: new Map(),
    directSupport: new Map(),
  }
}

function admitDerivationRecord(state: DerivationPlanningState, record: StoredRecord): void {
  const key = `${record.kindRecord}\u0000${record.id}`
  if (state.loaded.has(key)) return
  const records = state.loaded.size + 1
  if (records > state.limits.maxRecords) {
    throw derivationWorkExceeded('records', records, state.limits.maxRecords)
  }
  const bytes =
    state.bytes +
    new TextEncoder().encode(stableStringify(record as unknown as JsonValue)).byteLength
  if (bytes > state.limits.maxBytes) {
    throw derivationWorkExceeded('bytes', bytes, state.limits.maxBytes)
  }
  state.loaded.set(key, record)
  state.bytes = bytes
}

function admitDerivationGraphNode(state: DerivationPlanningState, factId: string): void {
  state.graphNodes.add(factId)
  if (state.graphNodes.size > state.limits.maxGraphNodes) {
    throw derivationWorkExceeded('graph_nodes', state.graphNodes.size, state.limits.maxGraphNodes)
  }
}

function admitDerivationGraphEdge(
  state: DerivationPlanningState,
  derivation: StoredDerivation,
  premise: DerivationPremise,
): void {
  state.graphEdges.add(`${derivation.key}\u0000${premise.kind}\u0000${premise.id}`)
  if (state.graphEdges.size > state.limits.maxGraphEdges) {
    throw derivationWorkExceeded('graph_edges', state.graphEdges.size, state.limits.maxGraphEdges)
  }
}

function publicDerivationWork(state: DerivationPlanningState): DerivationWork {
  return {
    records: state.loaded.size,
    bytes: state.bytes,
    graphNodes: state.graphNodes.size,
    graphEdges: state.graphEdges.size,
    limits: { ...state.limits },
  }
}

function emptyDerivationWork(limits: NormalizedDerivationWorkLimits): DerivationWork {
  return {
    records: 0,
    bytes: 0,
    graphNodes: 0,
    graphEdges: 0,
    limits: { ...limits },
  }
}

function publicRetrievalScanWork(state: RetrievalScanState): PhysicalScanWork {
  return {
    records: state.records,
    bytes: state.bytes,
    limits: { ...state.limits },
  }
}

function emptyPhysicalScanWork(limits: NormalizedArchiveLimits): PhysicalScanWork {
  return { records: 0, bytes: 0, limits: { ...limits } }
}

function normalizeIntegrityLimits(input: IntegrityOptions['limits']): NormalizedIntegrityLimits {
  if (
    input !== undefined &&
    (typeof input !== 'object' || input === null || Array.isArray(input))
  ) {
    throw new MemoryError('invalid_input', 'integrity limits must be an object')
  }
  const allowed = new Set(['maxRecords', 'maxBytes', 'maxGraphNodes', 'maxGraphEdges', 'maxIssues'])
  if (input !== undefined) {
    const unknown = Object.keys(input).find((key) => !allowed.has(key))
    if (unknown !== undefined) {
      throw new MemoryError('invalid_input', `integrity limits.${unknown} is not supported`)
    }
  }
  const limits: NormalizedIntegrityLimits = {
    maxRecords: input?.maxRecords ?? DEFAULT_INTEGRITY_RECORDS,
    maxBytes: input?.maxBytes ?? DEFAULT_INTEGRITY_BYTES,
    maxGraphNodes: input?.maxGraphNodes ?? DEFAULT_INTEGRITY_GRAPH_NODES,
    maxGraphEdges: input?.maxGraphEdges ?? DEFAULT_INTEGRITY_GRAPH_EDGES,
    maxIssues: input?.maxIssues ?? DEFAULT_INTEGRITY_ISSUES,
  }
  for (const [field, value, minimum, maximum] of [
    ['maxRecords', limits.maxRecords, 1, MAX_INTEGRITY_RECORDS],
    ['maxBytes', limits.maxBytes, 1, MAX_INTEGRITY_BYTES],
    ['maxGraphNodes', limits.maxGraphNodes, 1, MAX_INTEGRITY_GRAPH_NODES],
    ['maxGraphEdges', limits.maxGraphEdges, 1, MAX_INTEGRITY_GRAPH_EDGES],
    ['maxIssues', limits.maxIssues, 0, MAX_INTEGRITY_ISSUES],
  ] as const) {
    if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
      throw new MemoryError(
        'invalid_input',
        `integrity limits.${field} must be between ${minimum} and ${maximum}`,
      )
    }
  }
  return limits
}

function integrityLimitExceeded(
  dimension: 'records' | 'bytes' | 'graph_nodes' | 'graph_edges',
  required: number,
  maximum: number,
): MemoryError {
  return new MemoryError('result_too_large', `integrity verification exceeds ${dimension}`, {
    details: { phase: 'integrity', dimension, required, maximum },
  })
}

function createIntegrityPlanningState(limits: NormalizedIntegrityLimits): IntegrityPlanningState {
  return {
    limits,
    loaded: new Map(),
    bytes: 0,
    graphNodes: new Set(),
    graphEdges: new Set(),
    issuesDetected: 0,
    hasError: false,
  }
}

function admitIntegrityRecord(state: IntegrityPlanningState, record: StoredRecord): void {
  const key = `${record.kindRecord}\u0000${record.id}`
  if (state.loaded.has(key)) return
  const records = state.loaded.size + 1
  if (records > state.limits.maxRecords) {
    throw integrityLimitExceeded('records', records, state.limits.maxRecords)
  }
  const bytes =
    state.bytes +
    new TextEncoder().encode(stableStringify(record as unknown as JsonValue)).byteLength
  if (bytes > state.limits.maxBytes) {
    throw integrityLimitExceeded('bytes', bytes, state.limits.maxBytes)
  }
  state.loaded.set(key, record)
  state.bytes = bytes
}

function admitIntegrityGraphNode(state: IntegrityPlanningState, factId: string): void {
  state.graphNodes.add(factId)
  if (state.graphNodes.size > state.limits.maxGraphNodes) {
    throw integrityLimitExceeded('graph_nodes', state.graphNodes.size, state.limits.maxGraphNodes)
  }
}

function admitIntegrityGraphEdge(
  state: IntegrityPlanningState,
  derivation: StoredDerivation,
  premise: DerivationPremise,
): void {
  state.graphEdges.add(`${derivation.id}\u0000${premise.kind}\u0000${premise.id}`)
  if (state.graphEdges.size > state.limits.maxGraphEdges) {
    throw integrityLimitExceeded('graph_edges', state.graphEdges.size, state.limits.maxGraphEdges)
  }
}

function publicIntegrityWork(state: IntegrityPlanningState): IntegrityWork {
  return {
    records: state.loaded.size,
    bytes: state.bytes,
    graphNodes: state.graphNodes.size,
    graphEdges: state.graphEdges.size,
    issuesDetected: state.issuesDetected,
    issuesTruncated: state.issuesDetected > state.limits.maxIssues,
    limits: { ...state.limits },
  }
}

function rethrowIntegrityControlError(error: unknown): void {
  if (
    MemoryError.is(error, 'result_too_large') ||
    MemoryError.is(error, 'cancelled') ||
    MemoryError.is(error, 'timeout')
  ) {
    throw error
  }
}

function restoreDerivationWork(
  storedWork: JsonValue | undefined,
  fallbackLimits: NormalizedDerivationWorkLimits,
  label: string,
): DerivationWork {
  if (storedWork === undefined) {
    return {
      records: 0,
      bytes: 0,
      graphNodes: 0,
      graphEdges: 0,
      limits: { ...fallbackLimits },
    }
  }
  if (typeof storedWork !== 'object' || storedWork === null || Array.isArray(storedWork)) {
    throw new MemoryError('integrity_failed', `settled ${label} work is invalid`)
  }
  const value = storedWork as Readonly<Record<string, JsonValue>>
  const rawLimits = value.limits
  if (typeof rawLimits !== 'object' || rawLimits === null || Array.isArray(rawLimits)) {
    throw new MemoryError('integrity_failed', `settled ${label} work limits are invalid`)
  }
  const limitValues = rawLimits as Readonly<Record<string, JsonValue>>
  if (
    Object.keys(value).sort().join(',') !== 'bytes,graphEdges,graphNodes,limits,records' ||
    Object.keys(limitValues).sort().join(',') !== 'maxBytes,maxGraphEdges,maxGraphNodes,maxRecords'
  ) {
    throw new MemoryError('integrity_failed', `settled ${label} work shape is invalid`)
  }
  const numbers = [
    value.records,
    value.bytes,
    value.graphNodes,
    value.graphEdges,
    limitValues.maxRecords,
    limitValues.maxBytes,
    limitValues.maxGraphNodes,
    limitValues.maxGraphEdges,
  ]
  if (
    numbers.some(
      (number, index) => !Number.isSafeInteger(number) || Number(number) < (index < 4 ? 0 : 1),
    )
  ) {
    throw new MemoryError('integrity_failed', `settled ${label} work is invalid`)
  }
  const work = cloneJson(storedWork) as unknown as DerivationWork
  if (
    work.limits.maxRecords > MAX_DERIVATION_WORK_RECORDS ||
    work.limits.maxBytes > MAX_DERIVATION_WORK_BYTES ||
    work.limits.maxGraphNodes > MAX_DERIVATION_GRAPH_NODES ||
    work.limits.maxGraphEdges > MAX_DERIVATION_GRAPH_EDGES ||
    work.records > work.limits.maxRecords ||
    work.bytes > work.limits.maxBytes ||
    work.graphNodes > work.limits.maxGraphNodes ||
    work.graphEdges > work.limits.maxGraphEdges
  ) {
    throw new MemoryError('integrity_failed', `settled ${label} work exceeds its limits`)
  }
  return work
}

/**
 * JSON object properties whose value is `undefined` serialize as absence, while array entries do
 * not. Normalize that distinction once before either storage adapter sees a record, then let the
 * JSON validator reject holes, unsupported values, cycles, and non-plain objects. This keeps the
 * in-memory adapter byte-for-byte compatible with SurrealDB's bound-value serialization.
 */
function stripUndefinedObjectProperties(value: unknown, seen = new Set<object>()): void {
  if (typeof value !== 'object' || value === null || seen.has(value)) return
  seen.add(value)
  if (Array.isArray(value)) {
    for (const item of value) stripUndefinedObjectProperties(item, seen)
    return
  }
  const mutable = value as Record<string, unknown>
  for (const key of Object.keys(mutable)) {
    const item = mutable[key]
    if (item === undefined) delete mutable[key]
    else stripUndefinedObjectProperties(item, seen)
  }
}

function archiveLimitExceeded(
  phase: 'scan' | 'archive' | 'import',
  dimension: 'records' | 'bytes' | 'json_nodes',
  required: number,
  maximum: number,
): MemoryError {
  return new MemoryError('result_too_large', `canonical archive ${phase} exceeds ${dimension}`, {
    details: { phase, dimension, required, maximum },
  })
}

function validateArchiveJsonResources(value: unknown, maximumBytes: number): void {
  try {
    validateJson(value, 'canonical archive', {
      maxNodes: MAX_ARCHIVE_JSON_NODES,
      maxStringBytes: maximumBytes,
    })
  } catch (error) {
    if (MemoryError.is(error, 'invalid_input')) {
      if (error.message.includes('JSON nodes')) {
        throw archiveLimitExceeded(
          'archive',
          'json_nodes',
          MAX_ARCHIVE_JSON_NODES + 1,
          MAX_ARCHIVE_JSON_NODES,
        )
      }
      if (error.message.includes('UTF-8 string bytes')) {
        throw archiveLimitExceeded('archive', 'bytes', maximumBytes + 1, maximumBytes)
      }
    }
    throw error
  }
}

