function encodeOpaqueCursor(cursor: object): string {
  const bytes = new TextEncoder().encode(JSON.stringify(cursor))
  let binary = ''
  for (const byte of bytes) binary += String.fromCharCode(byte)
  return btoa(binary).replaceAll('+', '-').replaceAll('/', '_').replaceAll('=', '')
}

function decodeSyncConflictCursor(value: string): SyncConflictCursor {
  // v1 embedded the complete (up to 8 KiB, JSON-escaped) sync key. Accept those cursors during
  // migration, but v2 emits only the fixed-size conflict id.
  assertString(value, 'cursor', MAX_LEGACY_SYNC_CONFLICT_CURSOR_BYTES)
  try {
    const base64 = value.replaceAll('-', '+').replaceAll('_', '/')
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, '=')
    const binary = atob(padded)
    const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0))
    const parsed = JSON.parse(new TextDecoder().decode(bytes)) as unknown
    const cursor = importObject(parsed, 'cursor')
    assertString(cursor.spaceId, 'cursor.spaceId', 512)
    assertString(cursor.sessionId, 'cursor.sessionId', 512)
    if (cursor.v === 1) {
      if (
        stableStringify(Object.keys(cursor).sort(compareUnicode)) !==
        stableStringify(['lastKey', 'sessionId', 'spaceId', 'v'])
      ) {
        throw new Error('invalid v1 fields')
      }
      assertString(cursor.lastKey, 'cursor.lastKey', MAX_SYNC_RECORD_KEY_BYTES)
      return cursor as unknown as SyncConflictCursorV1
    }
    if (
      cursor.v !== 2 ||
      stableStringify(Object.keys(cursor).sort(compareUnicode)) !==
        stableStringify(['lastId', 'sessionId', 'spaceId', 'v'])
    ) {
      throw new Error('invalid v2 fields')
    }
    assertString(cursor.lastId, 'cursor.lastId', 128)
    if (!/^sync_conflict_[a-f0-9]{64}$/u.test(cursor.lastId)) {
      throw new Error('invalid conflict id')
    }
    return cursor as unknown as SyncConflictCursorV2
  } catch (error) {
    throw new MemoryError('invalid_input', 'sync conflict cursor is invalid', { cause: error })
  }
}

function encodeSyncHistoryCompactionCursor(cursor: SyncHistoryCompactionCursor): string {
  return encodeOpaqueCursor(cursor)
}

function decodeSyncHistoryCompactionCursor(value: string): SyncHistoryCompactionCursor {
  assertString(value, 'cursor', 4_096)
  try {
    const base64 = value.replaceAll('-', '+').replaceAll('_', '/')
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, '=')
    const binary = atob(padded)
    const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0))
    const parsed = JSON.parse(new TextDecoder().decode(bytes)) as unknown
    assertJson(parsed, 'cursor')
    const cursor = importObject(parsed, 'cursor')
    if (
      cursor.v !== 1 ||
      typeof cursor.spaceId !== 'string' ||
      typeof cursor.spaceGeneration !== 'string' ||
      cursor.spaceGeneration.length === 0 ||
      !Array.isArray(cursor.accessScopes) ||
      !Number.isInteger(cursor.expectedRevision) ||
      Number(cursor.expectedRevision) < 0 ||
      typeof cursor.expectedHead !== 'string' ||
      !/^[a-f0-9]{64}$/u.test(cursor.expectedHead) ||
      typeof cursor.before !== 'string' ||
      typeof cursor.lastCreatedAt !== 'string' ||
      typeof cursor.lastId !== 'string' ||
      cursor.lastId.length === 0
    ) {
      throw new Error('cursor fields are invalid')
    }
    assertInstant(cursor.before, 'cursor.before')
    assertInstant(cursor.lastCreatedAt, 'cursor.lastCreatedAt')
    const accessScopes = normalizeScopes(cursor.accessScopes as string[])
    if (stableStringify(accessScopes) !== stableStringify(cursor.accessScopes as JsonValue)) {
      throw new Error('cursor access scopes are not canonical')
    }
    return { ...(cursor as unknown as SyncHistoryCompactionCursor), accessScopes }
  } catch (error) {
    throw new MemoryError('invalid_input', 'sync history compaction cursor is invalid', {
      cause: error,
    })
  }
}

