function decodeSyncBundleCursor(value: string): SyncBundleCursor {
  assertString(value, 'cursor', 4_096)
  try {
    const base64 = value.replaceAll('-', '+').replaceAll('_', '/')
    const padded = base64.padEnd(Math.ceil(base64.length / 4) * 4, '=')
    const binary = atob(padded)
    const bytes = Uint8Array.from(binary, (character) => character.charCodeAt(0))
    const parsed = JSON.parse(new TextDecoder().decode(bytes)) as unknown
    assertJson(parsed, 'cursor')
    const cursor = importObject(parsed, 'cursor')
    const allowedFields = new Set([
      'v',
      'spaceId',
      'spaceGeneration',
      'accessScopes',
      'revision',
      'metadataRevision',
      'checkpointId',
      'maxCheckpoints',
      'maxCheckpointBytes',
      'phase',
      'checkpointCount',
      'checkpointByteLength',
      'checkpointDigest',
      'chunkIndex',
      'lastCreatedAt',
      'lastId',
    ])
    if (
      cursor.v !== 2 ||
      Object.keys(cursor).some((key) => !allowedFields.has(key)) ||
      typeof cursor.spaceId !== 'string' ||
      typeof cursor.spaceGeneration !== 'string' ||
      cursor.spaceGeneration.length === 0 ||
      !Array.isArray(cursor.accessScopes) ||
      !Number.isSafeInteger(cursor.revision) ||
      Number(cursor.revision) < 0 ||
      !Number.isSafeInteger(cursor.metadataRevision) ||
      Number(cursor.metadataRevision) < 0 ||
      typeof cursor.checkpointId !== 'string' ||
      !/^[a-f0-9]{64}$/u.test(cursor.checkpointId) ||
      !Number.isSafeInteger(cursor.maxCheckpoints) ||
      Number(cursor.maxCheckpoints) < 1 ||
      Number(cursor.maxCheckpoints) > MAX_SYNC_BUNDLE_CHECKPOINTS ||
      !Number.isSafeInteger(cursor.maxCheckpointBytes) ||
      Number(cursor.maxCheckpointBytes) < 1 ||
      Number(cursor.maxCheckpointBytes) > MAX_SYNC_BUNDLE_CHECKPOINT_BYTES ||
      !['headers', 'genesis', 'chunks', 'commit'].includes(String(cursor.phase)) ||
      !Number.isSafeInteger(cursor.checkpointCount) ||
      Number(cursor.checkpointCount) < 0 ||
      Number(cursor.checkpointCount) > Number(cursor.maxCheckpoints) ||
      !Number.isSafeInteger(cursor.checkpointByteLength) ||
      Number(cursor.checkpointByteLength) < 0 ||
      Number(cursor.checkpointByteLength) > Number(cursor.maxCheckpointBytes) ||
      typeof cursor.checkpointDigest !== 'string' ||
      !/^[a-f0-9]{64}$/u.test(cursor.checkpointDigest) ||
      !Number.isSafeInteger(cursor.chunkIndex) ||
      Number(cursor.chunkIndex) < 0 ||
      (cursor.lastCreatedAt === undefined) !== (cursor.lastId === undefined) ||
      (cursor.lastCreatedAt !== undefined && typeof cursor.lastCreatedAt !== 'string') ||
      (cursor.lastId !== undefined &&
        (typeof cursor.lastId !== 'string' || cursor.lastId.length === 0))
    ) {
      throw new Error('cursor fields are invalid')
    }
    if (typeof cursor.lastCreatedAt === 'string') {
      assertInstant(cursor.lastCreatedAt, 'cursor.lastCreatedAt')
    }
    const accessScopes = normalizeScopes(cursor.accessScopes as string[])
    if (stableStringify(accessScopes) !== stableStringify(cursor.accessScopes as JsonValue)) {
      throw new Error('cursor access scopes are not canonical')
    }
    return { ...(cursor as unknown as SyncBundleCursor), accessScopes }
  } catch (error) {
    throw new MemoryError('invalid_input', 'sync bundle cursor is invalid', { cause: error })
  }
}

